 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_changeDiv_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_changeDiv_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeDiv(1)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25502.btn_changeDiv_onclick' }); }
};

